 if(a==='finish-compose'){if(temp.mode==='augmentation'&&!temp.request){toast('先给AI一个具体请求，再由你选择与组合。');return;}const good=temp.art.product===caseData().sprite&&temp.art.headline<3;completeRound(good,good?'产品与表达对上了品牌要求。你保留了画面与文案的决定权。':'产品或表达出现偏离，最终质检需要修正。创意不能只靠看起来新鲜。',good?'这张广告，开始有自己的样子。':'很有想法，但还需要对准品牌。',good?'AI可以给素材，选择与表达还是你的。':'点子挺勇，产品也差点勇成另一个品牌。');return;}
